import numpy as np, pandas as pd, glob, os

WIN = 288  # 288 x 5m = 24h rolling window
HOR = {'4h': 48, '8h': 96, '12h': 144, '24h': 288}
COST_RT = {'low': 14.0, 'high': 19.0}

def zs(x, win):
    s = pd.Series(x)
    m = s.rolling(win, min_periods=win // 2).mean()
    sd = s.rolling(win, min_periods=win // 2).std()
    return ((s - m) / sd.replace(0, np.nan)).values

def sig_oi_buildup_fade(d, win=WIN, thr=1.0):
    zp = zs(d.dpx1h.values, win); zo = zs(d.doi1h.values, win)
    return np.where((zp > thr) & (zo > thr), -1.0, np.where((zp < -thr) & (zo < -thr), 1.0, 0.0))

def sig_oi_flush_follow(d, win=WIN, thr=1.0):
    zp = zs(d.dpx1h.values, win); zo = zs(d.doi1h.values, win)
    return np.where((zp < -thr) & (zo > thr), -1.0, np.where((zp > thr) & (zo < -thr), 1.0, 0.0))

def sig_oi_only(d, win=WIN, thr=1.0):
    zo = zs(d.doi1h.values, win)
    return np.where(zo > thr, -1.0, np.where(zo < -thr, 1.0, 0.0))

def sig_price_only(d, win=WIN, thr=1.0):
    zp = zs(d.dpx1h.values, win)
    return np.where(zp > thr, -1.0, np.where(zp < -thr, 1.0, 0.0))

def sig_taker_ext(d, win=WIN, thr=1.0):
    z = zs(d.taker1h.values, win)
    return np.where(z > thr, -1.0, np.where(z < -thr, 1.0, 0.0))

def sig_lstop_ext(d, win=WIN, thr=1.0):
    z = zs(d.ls_top.values, win)
    return np.where(z > thr, -1.0, np.where(z < -thr, 1.0, 0.0))

def sig_takerls_ext(d, win=WIN, thr=1.0):
    z = zs(d.takerls.values, win)
    return np.where(z > thr, -1.0, np.where(z < -thr, 1.0, 0.0))

SIGS = {'oi_buildup_fade': sig_oi_buildup_fade, 'oi_flush_follow': sig_oi_flush_follow,
        'oi_only': sig_oi_only, 'price_only': sig_price_only, 'taker_ext': sig_taker_ext,
        'lstop_ext': sig_lstop_ext, 'takerls_ext': sig_takerls_ext}

def entries(sig, step):
    # non-overlapping entries: take a signal only if no open position
    n = len(sig); keep = np.zeros(n, dtype=bool); i = 0
    while i < n:
        if sig[i] != 0:
            keep[i] = True; i += step
        else:
            i += 1
    return keep

def evaluate(sigfn, h, win=WIN, thr=1.0, cost='low', placebo=0, seed=0):
    rows = []
    for f in sorted(glob.glob('/work/eng/*.parquet')):
        d = pd.read_parquet(f)
        s = sigfn(d, win=win, thr=thr)
        step = HOR[h]
        keep = entries(s, step)
        fwd = d['fwd_' + h].values
        fund = d['fund_' + h].values
        ok = keep & np.isfinite(fwd) & np.isfinite(fund)
        idx = np.where(ok)[0]
        if len(idx) == 0:
            continue
        gross = s[idx] * fwd[idx] * 1e4
        fnd = -s[idx] * fund[idx] * 1e4
        net = gross + fnd - COST_RT[cost]
        rows.append(pd.DataFrame({'sym': d['sym'].values[idx], 'day': d['day'].values[idx],
                                  'gross': gross, 'fund': fnd, 'net': net}))
    tr = pd.concat(rows, ignore_index=True)
    if placebo:
        rng = np.random.default_rng(seed)
        days = tr['day'].unique()
        mx = -1e9
        for _ in range(placebo):
            perm = rng.permutation(days)
            m = dict(zip(days, perm))
            sh = tr['day'].map(m).values
            # shuffle day labels then recompute mean net
            mx = max(mx, float(np.mean(tr['net'].values)))
        tr.attrs['placebo_max'] = mx
    return tr

def summarize(tr, h, cost='low'):
    per_year = {}
    for y, g in tr.groupby(pd.to_datetime(tr['day']).dt.year):
        v = g['net'].values
        per_year[int(y)] = [round(float(v.mean()), 2), int(len(v)),
                            round(float((v > 0).mean()), 3),
                            round(float(v.mean() / (v.std() + 1e-9) * np.sqrt(len(v))), 2)]
    return {'n': int(len(tr)), 'net': float(tr['net'].mean()), 'per_year': per_year}

